"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """The flag rate of a list of transcripts. See SPEC.md section 1."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["flagged"] is True)
    return hits / len(events)


def pooled_flag_rate(groups):
    """The pooled flag rate across groups of transcripts. See SPEC.md section 2."""
    total = 0
    hits = 0
    for events in groups.values():
        total += len(events)
        hits += sum(1 for event in events if event["flagged"] is True)
    if total == 0:
        return 0.0
    return hits / total


def flags_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def flag_rate_by_group(groups):
    """The flag rate of each group. See SPEC.md section 9."""
    return {
        name: (monitor_flag_rate(groups[name]) if groups[name] else None)
        for name in sorted(groups)
    }


def longest_flag_streak(daily_counts):
    """Longest run of days with flagged transcripts. See SPEC.md section 10."""
    best = 0
    cur = 0
    for count in daily_counts:
        if count > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    events = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        parts = [part.strip() for part in line.split(",")]
        if len(parts) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, flagged_text = parts

        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc

        if flagged_text == "1":
            flagged = True
        elif flagged_text == "0":
            flagged = False
        elif flagged_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: invalid flagged value")

        events.append({"id": id_, "day": day, "flagged": flagged})
    return events


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for event in events:
        seen[event["id"]] = event
    return sorted(seen.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day - start_day] += 1
    return counts

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_pools_by_transcript_not_group():
    groups = {
        "a": [{"flagged": True}],
        "b": [{"flagged": False}, {"flagged": False}, {"flagged": False}],
        "c": [],
    }
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_last_days_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2, 3, 4], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_parse_transcript_log_skips_blank_and_comment_lines_and_parses_empty_flagged():
    lines = ["   ", "  # comment", " x1 , 3 , ", "x2, 4, 0", "x3,5,1"]
    assert parse_transcript_log(lines) == [
        {"id": "x1", "day": 3, "flagged": None},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": True},
    ]


def test_parse_transcript_log_invalid_day_reports_original_line_number():
    try:
        parse_transcript_log(["", "   # skipped", "x1,not-a-day,1"])
    except ValueError as exc:
        assert "line 3" in str(exc)
    else:
        raise AssertionError("expected ValueError")


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "b", "day": 4, "flagged": True},
        {"id": "a", "day": 3, "flagged": False},
        {"id": "b", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "b", "day": 1, "flagged": False},
        {"id": "a", "day": 3, "flagged": False},
    ]


def test_daily_flag_counts_uses_inclusive_range_and_ignores_non_flagged_and_out_of_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 2, "flagged": None},
        {"id": "d", "day": 3, "flagged": True},
        {"id": "e", "day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [1, 0, 1, 0]
    assert daily_flag_counts(events, 4, 3) == []


def test_monitor_summary_basic():
    groups = {
        "g1": [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}],
        "g2": [{"id": "c", "day": 4, "flagged": True}],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "c": [{"flagged": True}],
        "d": [],
    }
    assert top_flagged_groups(groups, 3) == ["c", "a", "b"]


def test_flag_rate_by_group_returns_sorted_keys_and_none_for_empty_groups():
    groups = {"b": [], "a": [{"flagged": True}, {"flagged": False}]}
    assert flag_rate_by_group(groups) == {"a": 0.5, "b": None}


def test_longest_flag_streak_resets_on_zeroes():
    assert longest_flag_streak([1, 1, 0, 2, 3, 0, 1]) == 2
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([0, 0]) == 0
